DO $guard$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(g.source_url || ' 預期 ' || g.expected || ' 實際 ' || COALESCE(a.n, 0), ', ') INTO bad
    FROM (VALUES
    ('https://web.cec.gov.tw/api/file/bb9a8d7a-9b8a-41ec-8e23-33efd009385a.pdf', 23),
    ('https://web.cec.gov.tw/api/file/370f3bbf-6408-4fdc-b8d8-9b9214913f74.pdf', 58),
    ('https://web.cec.gov.tw/api/file/ccd7e51a-5fd0-4ea0-a81b-a120cd550c9c.pdf', 610),
    ('https://web.cec.gov.tw/api/file/9ccb6224-20be-479e-931f-81aa6155f28a.pdf', 892),
    ('https://web.cec.gov.tw/api/file/a7b4f3d3-dad3-4e61-9036-2cd21cf29d92.pdf', 465),
    ('https://web.cec.gov.tw/api/file/437a9da7-eaa7-47b9-9571-789eeb48ed18.pdf', 3437),
    ('https://web.cec.gov.tw/api/file/1278f66e-1d15-4ecf-aeeb-9ea5cba61f00.pdf', 16),
    ('https://web.cec.gov.tw/api/file/f3b665f2-6f0b-485f-a1eb-17d152849317.pdf', 94),
    ('https://web.cec.gov.tw/api/file/f1abbda2-229b-4a02-8dfb-58beb3ceca61.pdf', 14100),
    ('https://web.cec.gov.tw/api/file/729644ff-cb01-42bb-a052-c9b3c55a1289.pdf', 892)
    ) AS g(source_url, expected)
    LEFT JOIN (SELECT source_url, count(*) AS n FROM cec_registrations GROUP BY 1) a ON a.source_url = g.source_url
   WHERE COALESCE(a.n, 0) <> g.expected;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'cec_registrations 列數對不上：%', bad; END IF;
  IF (SELECT count(*) FROM cec_registrations WHERE election_id = 2026) <> 20587 THEN
    RAISE EXCEPTION 'cec_registrations 合計不是 20587';
  END IF;
  IF (SELECT count(*) FROM cec_registrations r JOIN cec_registration_sources s USING (source_url) WHERE s.superseded_by IS NULL) <> 19695 THEN
    RAISE EXCEPTION 'cec_registrations 現行版合計不是 19695';
  END IF;
END
$guard$;

ANALYZE cec_registrations;

